}
.selectTrigger [data-slot="select-value"] {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group[data-variant="toolbar"] {
