  font-weight: var(--v4-type-label-font-weight);
}
.card[data-variant="framed"] > .cardHeader .cardAction > a:not([data-slot]) {
  color: inherit;
  text-decoration: none;
}
.card[data-variant="framed"] > .cardHeader .cardAction > a:not([data-slot]):hover {
  color: var(--v4-ink);
  text-decoration: underline;
}
.card[data-variant="framed"] > .cardBody,
.card[data-variant="framed"] > .cardFooter {
