  margin-inline-start: auto;
  grid-column: 2;
  grid-row: 1;
}
.cardFooter {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-space-12) var(--v4-card-inset);
  padding-inline-start: calc(var(--v4-card-inset) + var(--v4-card-lead));
  border-top: var(--v4-size-control-border) solid var(--v4-line);
  color: var(--v4-text2);
  overflow-wrap: anywhere;
}
.choice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  cursor: pointer;
}
.choiceText {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.choiceTitle {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
  color: var(--v4-ink);
}
.choiceDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
}
.choiceRow {
  align-items: center;
  justify-content: space-between;
  padding-block: 12px;
  border-bottom: 1px solid var(--v4-line-soft);
}
.switch {
  --v4-switch-travel: 16px;
  box-sizing: border-box;
  border: var(--v4-size-control-border) solid transparent;
  background-color: var(--v4-switch-off-surface);
  transition-property: background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-standard);
}
.switch[data-size="default"] {
  width: 36px;
  height: 20px;
  padding: 2px;
}
.switch[data-size="sm"] {
  --v4-switch-travel: 12px;
  width: 28px;
  height: 16px;
  padding: 2px;
}
.switchThumb {
  width: 14px;
  height: 14px;
  background-color: var(--v4-switch-thumb);
  box-shadow:
    0 0 0 var(--v4-size-control-border) var(--v4-switch-thumb-line),
    0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
  transition-property: background-color, box-shadow;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.switch[data-size="sm"] > .switchThumb {
  width: 10px;
  height: 10px;
}
.switch[data-state="checked"] {
  background-color: var(--v4-sw-on);
}
.switch[data-state="checked"] > .switchThumb {
  background-color: var(--v4-sw-knob-on);
  box-shadow: 0 1px 2px color-mix(in oklab, var(--v4-frame) 24%, transparent);
}
.radioGroup [data-slot="label"] {
  font-weight: var(--v4-type-body-font-weight);
}
.switch[aria-invalid="true"] {
  border-color: var(--v4-control-invalid-border);
}
.check[data-slot="checkbox"] {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.choiceMark {
  border: var(--v4-size-control-border) solid var(--v4-control);
  background-color: var(--v4-control-surface);
  color: var(--v4-on-ink);
  transition-property: background-color, border-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.choiceMark:is([data-state="checked"], [data-state="indeterminate"]) {
  border-color: var(--v4-ink);
  background-color: var(--v4-ink);
}
.choiceMark[aria-invalid="true"]:not([data-state="checked"], [data-state="indeterminate"]) {
  border-color: var(--v4-control-invalid-border);
}
.radioDot {
  position: absolute;
  top: 50%;
  left: 50%;
  width: var(--v4-space-8);
  height: var(--v4-space-8);
  translate: -50% -50%;
  border-radius: 50%;
  background-color: var(--v4-on-ink);
}
.check [data-slot="checkbox-indicator"] > svg {
  grid-area: 1 / 1;
}
.check [data-mixed],
.check[data-state="indeterminate"] [data-check] {
  opacity: 0;
  transition: opacity var(--v4-duration-fast) var(--v4-ease-fade);
}
.check[data-state="indeterminate"] [data-mixed] {
  opacity: 1;
}
.progressGroup {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.progress {
